css:
.loader {
  position: relative;
  width: 56px;
  height: 46px;
}
.loader::before {
  content: "";
  position: absolute;
  left: 4px;
  bottom: 10px;
  width: 46px;
  height: 0;
  border-top: 2px dashed #c7d2fe;
  transform: rotate(-20deg);
  transform-origin: left center;
}
.loader i {
  position: absolute;
  width: 16px;
  height: 16px;
  background: #6366f1;
  clip-path: polygon(0 0, 100% 50%, 0 100%, 26% 50%);
  animation: fly 1.8s ease-in-out infinite;
}
@keyframes fly {
  0% { transform: translate(0, 30px) rotate(-12deg); opacity: 0; }
  15% { opacity: 1; }
  85% { opacity: 1; }
  100% { transform: translate(42px, -4px) rotate(8deg); opacity: 0; }
}
